class Solution:
    def sumOfSquares(self, nums: List[int]) -> int:
        n = len(nums)
        return sum(v * v for i, v in enumerate(nums, 1) if n % i == 0)

c.cpp:
class Solution {
public:
    int sumOfSquares(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        for (int i = 1; i <= n; i++)
            if (n % i == 0) ans += nums[i - 1] * nums[i - 1];
        return ans;
    }
};

